/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void rsr_timing (void)
{
	os_pte_wait (rsr_vars.pte) ;
	
	if ((rsr_vars.running.ms += RSR_PTE_TIMEOUT) >= 1000)
	{
		rsr_vars.running.ms = 0 ;                
		
    if (++rsr_vars.running.sec == 60)
		{
		 	rsr_vars.running.sec = 0 ;
		 	rsr_vars.running.min++   ;
 
      rsr_vars.runtime_remaining = rsr_opt.runtime - rsr_vars.running.min ;

			rf_sound_set   ((Rf_Sound_Def)(rsr_opt.runtime - rsr_vars.running.min), FALSE)  ;
		}
	} 

  #if DBG_RSR == 1
    dbg_tx_text("\r\nTime : ") ;
    dbg_tx_u(RSR_CUR_TIME / RSR_PTE_TIMEOUT , 5) ;
  #endif

}    

//--------------------------------------------------------------------------//

void rsr_timing_reset (void)
{
  
    rsr_vars.running.ms = rsr_vars.running.sec = rsr_vars.running.min = 0 ;    
  
}
